<js>
function setArgument(key, value) {
    let open_argument = source.getVariable();
    open_argument = getArguments(open_argument,'');
    open_argument[key] = value;
    open_argument = JSON.stringify(open_argument);
    source.setVariable(open_argument);
    return open_argument;
}

function gets_key() {
    var servers = String(source.bookSourceUrl);
    const serverList = servers.split('\n');

    for (let server of serverList) {
        let keys = String(cookie.getCookie(server)) || String(java.getCookie(server));
        if (keys) {
            let keyParts = keys.split('secretKey=');
            if (keyParts.length > 1) {
                keys = keyParts[keyParts.length - 1];
                setArgument('key', keys);
                return keys;
            }
        }
    }
    return '';  
 }

let open_argument = source.getVariable();
let base_url = getArguments(open_argument,'server');
let tone_id = getArguments(open_argument,'tone_id');
let key = getArguments(open_argument,'key');
if (!key) {
	key = gets_key();
	}

var datadist = {
  "-1": "纯净阅读",
  "-2": "纯净漫画",
  "51": "多人发音",
  "0": "默认发音",
  "1": "甜美少女",
  "2": "清亮青叔",
  "5": "开朗青年",
  "6": "温柔淑女",
  "4": "成熟大叔",
  "74": "大叔升级",
  '999':'喜马拉雅听书'
};

let ms;
ms = datadist[tone_id];
if (!ms) {
		ms = tone_id
		}

var tishi = '\n\n当前模式：'+ ms +'\n\n如切换,请切换请下拉刷新详情页\n由于缓存原因，已听的需要切换到下一章再切回来\n'


let res = result.split("\n")[0]
let media = res.split("_")[1] || 'fanqie'
let bookid = res.split("_")[0];
let info;
if (media == 'fanqie') {
try {
    info = JSON.parse(java.ajax(`${base_url}/tts_detail?&bookid=${bookid}`));
    } catch (error) {
        info = {'abstract': ""}
        }
} else {
    info = {'abstract': ""}
    }


if (!key) {
    jj = '\n\n❌️当前用户未填写密钥，请先输入密钥\n密钥获取途径，书籍详情页，点击右上角点击登陆，获取后，填写，再次刷新详情页'
    }
    else if (!info.abstract) {
    jj = ""
    } else {
    jj =tishi +  info.abstract
    }

</js>

