source.loginJs:
function login() {
    let zdyserver;
    try {
        zdyserver = String(source.getLoginInfoMap()['服务器地址(可不填)']);
        if (zdyserver.includes('http')) {
            setArgument('server', zdyserver);
            java.toast(`\n\n当前服务器为自定义服务器\n${zdyserver}\n\n切换服务器请先清空服务器地址中的数据`);
        }
    } catch (error) {
    }
    ;
    let zdytone_id;
    try {
        zdytone_id = String(source.getLoginInfoMap()['其他音色填写后点击右上角✔']);
        if (zdytone_id) {
            setArgument('tone_id', zdytone_id);
        }} catch (error) {
    }
    ;
}

function gets_key() {
    var servers = String(source.bookSourceUrl);
    const serverList = servers.split('\n');

    for (let server of serverList) {
        let key = String(cookie.getCookie(server)) || String(java.getCookie(server));
        if (key) {
            let keyParts = key.split('secretKey=');
            if (keyParts.length > 1) {
                key = keyParts[keyParts.length - 1];
                setArgument('key', key);
                return key;
            }
        }
    }

    return '';
}

// 填写密钥
function loginqt() {
    let key = gets_key()
    if (key && key != "") {
        java.toast("您已填写秘钥:" + key);
        return false
    }
    java.startBrowserAwait(getArgument('server') + '/check_key', '登录晴天小说书源');
    key = gets_key()
    if (key) {
        java.longToast('登录成功，秘钥：' + key);
        return true
    } else {
        java.toast('登录失败！！！！！');
        return false
    }
}

//登录番茄
function fq_login() {
    var cookies = cookie.getCookie('fanqienovel.com') || java.getCookie('fanqienovel.com')
    java.log(cookies)
    if (cookies && cookies != "") {
        java.toast("请不要重复登录，请先退出登录！")
        return false
    }
    try {
        java.startBrowserAwait("https://fanqienovel.com/", "登录")
    } catch (e) {
        java.toast(e)
    }
    try {
        cookie.removeCookie("snssdk.com")
    } catch (e) {
    }
    var cookies = cookie.getCookie("fanqienovel.com")
    if (!cookies || cookies == "") {
        java.toast("登录失败！")
        return false
    }
    java.toast("登录成功！")
    return true
}

//退出番茄
function logout() {
    cookie.removeCookie("fanqienovel.com");
    cookie.removeCookie("snssdk.com");
    //cookie.removeCookie(getArgument('server'));
    java.toast("退出登录成功");
}

//获取参数
function getArgument(key) {
    let open_argument = source.getVariable();
    return getArguments(open_argument, key);
}

//设置参数
function setArgument(key, value) {
    let open_argument = source.getVariable();
    open_argument = getArguments(open_argument, '');
    open_argument[key] = value;
    open_argument = JSON.stringify(open_argument);
    source.setVariable(open_argument);
    return open_argument;
}

//首页
function api() {
    java.startBrowserAwait(getArgument('server') + '/', "接口文档");
}

//打赏
function vip() {
    java.startBrowserAwait(getArgument('server') + '/coffee', "喝咖啡");
}

//获取密钥
function hqmy() {
    java.startBrowserAwait(getArgument('server') + '/key', "获取密钥");
}

var server = getArgument('server');

//获取搜索
function get_search() {
    var search = getArgument('search');
    var datadist = {
        "-1": "阅读模式",
        "-2": "漫画模式",
        "0": "音频模式",
    };
    var tishi = '\n\n当前搜索模式：' + datadist[search]
    java.toast(tishi);
    return search
}

//设置搜索
function set_search(mode, name) {
    setArgument('search', mode);
    setArgument('tone_id', mode);
    java.toast('\n\n已切换至' + name);
}

//获取服务器
function get_server() {
    var server = getArgument('server');
    var tishi = '\n\n当前服务器：' + server
    java.toast(tishi);
    return server
}


//设置服务器
function set_server() {
    let zdyserver;
    try {
        zdyserver = String(source.getLoginInfoMap()['服务器地址(可不填)']);
        if (zdyserver.includes('http')) {
            setArgument('server', zdyserver);
            java.toast(`\n\n当前服务器为自定义服务器\n${zdyserver}\n\n切换服务器请先清空服务器地址中的数据`);
        } else {
            zdyserver = '';
        }
    } catch (error) {
        zdyserver = '';
    }
    ;
    if (!zdyserver) {
        const servers = String(source.bookSourceUrl).split('\n').map(s => s.trim()).filter(s => s && !s.includes('提示'));
        const currentServer = getArgument('server') || '';
        const currentIndex = servers.indexOf(currentServer);

        const nextIndex = currentIndex >= 0 ? (currentIndex + 1) % servers.length : 0;
        const nextServer = servers[nextIndex];

        setArgument('server', nextServer);
        java.toast(`\n\n当前服务器${nextIndex+1}:${nextServer}\n\n注意：切换服务器后需要在详情页刷新目录才能生效`);
    }
}


//获取音色
var tone_id = getArgument('tone_id');

function get_tone_id(arg) {
    var datadist = {
        "0": "默认音色",
        "-1": "阅读模式",
        "-2": "漫画模式",
        "51": "多人发音",
        "1": "甜美少女",
        "2": "清亮青叔",
        "5": "开朗青年",
        "6": "温柔淑女",
        "4": "成熟大叔",
        "74": "大叔升级",
        "30": "优雅御姐"
    };
    var tone_id = datadist[arg] || arg;
    var tishi = '\n\n当前音色：' + tone_id;
    java.toast(tishi);
}

//设置音色
function set_tone_id(mode, name) {
    let zdytone_id;
    try {
        zdytone_id = String(source.getLoginInfoMap()['其他音色填写后点击右上角✔']);
        if (zdytone_id) {
            setArgument('tone_id', zdytone_id);
            java.toast(`\n\n当前音色为自定义音色\n${zdytone_id}\n\n切换音色请先清空音色输入框中的数据`);
        } else {
            zdytone_id = '';
        }
    } catch (error) {
        zdytone_id = '';
    }
    if (!zdytone_id) {
        let toast = "\n\n已切换至：" + name + '\n\n切换后需要刷新详情页';
        setArgument('tone_id', mode);
        java.toast(toast);
    }
}

function zr() {
    let toast = '\n\n真人语音无法手动切换\n\n前往搜索找包含主播的书籍进入即可';
    java.toast(toast);
}

function mh() {
    let toast = '\n\n漫画无法手动切换\n\n前往搜索找包含主播的书籍进入即可';
    java.toast(toast);
}

